<?php require dirname(__DIR__).'/includes/bootstrap.php'; if(!empty($_SESSION['admin_id']))redirect('admin/index.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$stmt=$pdo->prepare('SELECT * FROM admins WHERE email=? LIMIT 1');$stmt->execute([$email]);$admin=$stmt->fetch();if($admin&&password_verify((string)($_POST['password']??''),$admin['password'])){session_regenerate_id(true);$_SESSION['admin_id']=$admin['id'];$_SESSION['admin_name']=$admin['name'];redirect('admin/index.php');}$error='Invalid email or password.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="<?=base_url('assets/admin.css')?>"></head><body class="login-page"><main class="login-card"><div class="login-seal">म & आ</div><span class="eyebrow">PRIVATE ADMIN</span><h1>Welcome back</h1><p>Manage personalized invitations and RSVPs.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" class="form-grid"><?=csrf_field()?><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="btn primary block">Sign in</button></form></main></body></html>

